import * as React from "react";

export type ArrowDashedUpIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function ArrowDashedUpIcon({ size = 20, ...props }: ArrowDashedUpIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M12 20v-3M12 14.5v-2.5M12 9.5V7" strokeDasharray="0.1 2.2" strokeWidth="2.4" strokeLinecap="round" /><path d="M7.5 10.5 12 6l4.5 4.5" />
    </svg>
  );
}
